1\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\",\\n      \\\"message\\\": \\\"DifferentiableAt.div.{u, u_1} {\ud835\udd5c : Type u} [NontriviallyNormedField \ud835\udd5c] {x : \ud835\udd5c} {\ud835\udd5c' : Type u_1}\\\\n  [NontriviallyNormedField \ud835\udd5c'] [NormedAlgebra \ud835\udd5c \ud835\udd5c'] {c d : \ud835\udd5c \u2192 \ud835\udd5c'} (hc : DifferentiableAt \ud835\udd5c c x)\\\\n  (hd : DifferentiableAt \ud835\udd5c d x) (hx : d x \u2260 0) : DifferentiableAt \ud835\udd5c (c / d) x\\\",\\n      \\\"line\\\": 9,\\n      \\\"column\\\": 1\\n    },\\n    {\\n      \\\"severity\\\": \\\"error\\\",\\n      \\\"message\\\": \\\"Unknown constant `DifferentiableAt.pow`\\\",\\n      \\\"line\\\": 10,\\n      \\\"column\\\": 8\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\",\\n      \\\"message\\\": \\\"exists_deriv_eq_slope (f : \u211d \u2192 \u211d) {a b : \u211d} (hab : a < b) (hfc : ContinuousOn f (Set.Icc a b))\\\\n  (hfd : DifferentiableOn \u211d f (Set.Ioo a b)) : \u2203 c \u2208 Set.Ioo a b, deriv f c = (f b - f a) / (b - a)\\\",\\n      \\\"line\\\": 11,\\n      \\\"column\\\": 1\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\",\\n      \\\"message\\\": \\\"Real.sq_sqrt {x : \u211d} (h : 0 \u2264 x) : \u221ax ^ 2 = x\\\",\\n      \\\"line\\\": 12,\\n      \\\"column\\\": 1\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\",\\n      \\\"message\\\": \\\"Real.sqrt_sq_eq_abs (x : \u211d) : \u221a(x ^ 2) = |x|\\\",\\n      \\\"line\\\": 13,\\n      \\\"column\\\": 1\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\",\\n      \\\"message\\\": \\\"Real.sqrt_sq {x : \u211d} (h : 0 \u2264 x) : \u221a(x ^ 2) = x\\\",\\n      \\\"line\\\": 14,\\n      \\\"column\\\": 1\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\",\\n      \\\"message\\\": \\\"Real.sqrt_mul_self {x : \u211d} (h : 0 \u2264 x) : \u221a(x * x) = x\\\",\\n      \\\"line\\\": 15,\\n      \\\"column\\\": 1\\n    },\\n    {\\n      \\\"severity\\\": \\\"info\\\"